(()=>{
'use strict';
const L={manifest:null,build:'',cache:new Map(),timer:null,patchTimer:null,refreshing:false,activeGroup:''};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const n=v=>v==null||v===''||!Number.isFinite(Number(v))?null:Number(v);
const fmt=(v,d=2)=>n(v)==null?'—':Number(v).toLocaleString('zh-TW',{maximumFractionDigits:d});
const pct=v=>n(v)==null?'—':`${Number(v)>0?'+':''}${fmt(v,2)}%`;
const compact=v=>n(v)==null?'—':new Intl.NumberFormat('zh-TW',{notation:'compact',maximumFractionDigits:1}).format(Number(v));
const view=()=>document.querySelector('.tab.active')?.dataset.view||'intraday';
const regime={BROAD_RISK_ON:'全面偏多',SELECTIVE_RISK_ON:'選股偏多',NEUTRAL:'中性',DEFENSIVE:'防守',RISK_OFF:'風險關閉'};
const freshness={LIVE:'即時',FRESH:'盤後定格',FROZEN:'收盤定格',STALE:'過期',UNKNOWN:'未知'};
const cfg=v=>v==='intraday'?{index:'decision_intraday_index',detail:'decision_intraday_detail',market:'market_intraday_context',score:'intraday_momentum_score',scoreLabel:'盤中動能'}:v==='daytrade'?{index:'decision_daytrade_index',detail:'decision_daytrade_detail',market:'market_intraday_context',score:'daytrade_score',scoreLabel:'當沖分'}:{index:'decision_close_index',detail:'decision_close_detail',market:'market_close_context',score:'swing_quality_score',scoreLabel:'波段品質'};
async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${url} HTTP ${r.status}`);return r.json()}
async function manifest(force=false){if(L.manifest&&!force)return L.manifest;const m=await json(`./data/current_manifest.json?liveui=${Date.now()}`);if(L.build&&L.build!==m.active_build_id)L.cache.clear();L.manifest=m;L.build=m.active_build_id||'';return m}
async function dataset(key){const m=await manifest(),meta=m.datasets?.[key];if(!meta)return null;const ck=`${m.active_build_id}:${key}`;if(L.cache.has(ck))return L.cache.get(ck);const x=await json(meta.url);L.cache.set(ck,x);return x}
async function detailMap(v=view()){const c=cfg(v),d=await dataset(c.detail);return d?.items||{}}
async function rows(v=view()){const c=cfg(v),x=await dataset(c.index);return Array.isArray(x)?x:[]}
function groupOf(r,f={}){return String(r?.primary_group||f?.primary_group||f?.industry||r?.industry||'').trim()}
async function groups(v=view()){
 const ck=`groups:${L.build}:${v==='daytrade'?'intraday':v}`;if(L.cache.has(ck))return L.cache.get(ck);
 const [idx,items]=await Promise.all([rows(v),detailMap(v)]),out={};
 for(const r of idx){const f=items[String(r.code)]||{},g=groupOf(r,f);if(!g)continue;(out[g]||(out[g]=[])).push({code:String(r.code),name:r.name||f.name||'',price:f.quote?.price??null,change:f.quote?.day_change_pct??null,rank:n(r.opportunity_rank)??999999,score:n((r.scores||{})[cfg(v).score])??n((f.scores||{})[cfg(v).score]),confidence:n(r.data_confidence)??n(f.data_confidence)});}
 for(const xs of Object.values(out))xs.sort((a,b)=>a.rank-b.rank||a.code.localeCompare(b.code));L.cache.set(ck,out);return out;
}
function style(){if($('#liveUi20261001Style'))return;const s=document.createElement('style');s.id='liveUi20261001Style';s.textContent=`
#marketPulse{display:none!important}.top{position:relative!important;top:auto!important}.tabs{top:62px!important;z-index:40!important}
#livePinnedBar{position:sticky;top:0;z-index:50;display:grid;grid-template-columns:minmax(92px,1.2fr) minmax(82px,1fr) minmax(76px,.9fr) auto;gap:6px;align-items:center;min-height:62px;padding:7px 10px;background:#253c33;color:#fff;box-shadow:0 2px 9px rgba(0,0,0,.18)}
.live-pulse-item{min-width:0}.live-pulse-item span{display:block;opacity:.76;font-size:.64rem}.live-pulse-item b{display:block;font-size:.83rem;line-height:1.15;white-space:nowrap}.live-pulse-item small{display:block;opacity:.82;font-size:.62rem;margin-top:2px;white-space:nowrap}.live-pulse-item .rise,.live-pulse-rise{color:#ffb5ad!important}.live-pulse-item .fall,.live-pulse-fall{color:#9fddbd!important}
#livePulseRefresh{border:1px solid rgba(255,255,255,.38);background:rgba(255,255,255,.08);color:#fff;border-radius:9px;padding:8px 7px;font-size:.66rem;font-weight:850;white-space:nowrap}#livePulseRefresh:disabled{opacity:.5}
.live-sector-preview{margin-top:5px!important;color:#4d6258!important;line-height:1.45!important;font-size:.7rem!important}.live-sector-members{margin-top:8px;padding-top:7px;border-top:1px dashed #dfe5df}.live-sector-title{font-size:.72rem;color:#607269;margin-bottom:6px}.live-sector-list{display:flex;flex-wrap:wrap;gap:6px}.live-member-btn{border:1px solid #d9e2dc;background:#fff;border-radius:999px;padding:6px 9px;font-size:.72rem;color:#355247}.live-member-btn:active{transform:scale(.98)}
.live-sector-rank{margin-top:9px;padding:9px 10px;border-radius:10px;background:var(--soft);border:1px solid var(--line)}.live-sector-rank-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px}.live-sector-rank-head b{font-size:.82rem}.live-sector-rank-head span{font-size:.68rem;color:var(--muted)}.live-sector-rank-list{display:grid;gap:5px}.live-sector-rank-row{display:grid;grid-template-columns:auto 1fr auto;gap:7px;align-items:center;border:1px solid var(--line);background:var(--card);border-radius:9px;padding:7px 8px;cursor:pointer;color:var(--ink)}.live-sector-rank-row strong{font-size:.76rem}.live-sector-rank-row small{display:block;color:var(--muted);font-size:.65rem;margin-top:2px}.live-sector-rank-score{text-align:right;font-size:.7rem}
@media(max-width:560px){#livePinnedBar{grid-template-columns:1.08fr 1fr .88fr auto;padding:6px 8px;gap:4px}.live-pulse-item b{font-size:.76rem}#livePulseRefresh{padding:7px 6px;font-size:.62rem}.tabs{top:62px!important}}
`;document.head.appendChild(s)}
function ensureBar(){style();let bar=$('#livePinnedBar');if(bar)return bar;bar=document.createElement('div');bar.id='livePinnedBar';bar.setAttribute('aria-label','即時市場資訊');bar.innerHTML='<div class="live-pulse-item"><span>加權指數</span><b>—</b><small>讀取中</small></div><div class="live-pulse-item"><span>櫃買指數</span><b>—</b><small>讀取中</small></div><div class="live-pulse-item"><span>環境分</span><b>—</b><small>讀取中</small></div><button id="livePulseRefresh" type="button">重新整理</button>';const app=$('#app');if(app)app.prepend(bar);return bar}
async function renderBar(){try{const v=view(),m=await manifest(),c=cfg(v),[ctx,raw]=await Promise.all([dataset(c.market),json(`../data/market.json?t=${Date.now()}`).catch(()=>null)]),ta=raw?.taiex||{},ot=raw?.otc||{},tc=n(ctx?.components?.taiex?.change_pct)??n(ta.change_pct),oc=n(ctx?.components?.otc?.change_pct)??n(ot.change_pct),tone=x=>n(x)==null?'':Number(x)>0?'live-pulse-rise':Number(x)<0?'live-pulse-fall':'',clock=String(ctx?.metrics?.quote_snapshot_time||ctx?.as_of||m.trade_date||'').replace('T',' ').slice(-8,-3)||'—',fr=freshness[ctx?.freshness]||ctx?.freshness||'—';const b=ensureBar(),cells=b.querySelectorAll('.live-pulse-item');cells[0].innerHTML=`<span>加權指數</span><b>${fmt(ta.close,2)}</b><small class="${tone(tc)}">${pct(tc)}</small>`;cells[1].innerHTML=`<span>櫃買指數</span><b>${fmt(ot.close,2)}</b><small class="${tone(oc)}">${pct(oc)}</small>`;cells[2].innerHTML=`<span>環境分</span><b>${fmt(ctx?.market_score,1)}/15</b><small>${esc(regime[ctx?.market_regime]||ctx?.market_regime||'—')} · ${esc(fr)} ${esc(clock)}</small>`}catch(e){console.warn('live pinned bar',e)}}
function quoteHtml(q){const p=n(q?.price),ch=n(q?.day_change_pct),tone=ch==null?'':ch>0?'rise':ch<0?'fall':'',turn=n(q?.turnover_value_twd);return `<div class="quote-strip live-injected-quote"><div class="quote-price">${fmt(p,2)}</div><div class="quote-change ${tone}">${pct(ch)}</div><div class="quote-volume">即時價</div>${turn!=null?`<div class="quote-turnover">成交值 ${compact(turn)}元</div>`:''}</div>`}
async function patchPrices(){try{const items=await detailMap(),cards=document.querySelectorAll('#cards .card[data-code]');for(const card of cards){if(card.querySelector('.quote-strip'))continue;const f=items[String(card.dataset.code)]||{},q=f.quote||{};if(n(q.price)==null)continue;card.querySelector('.card-top')?.insertAdjacentHTML('afterend',quoteHtml(q))}}catch(e){console.warn('live candidate price patch',e)}}
function chipGroup(chip){const t=chip?.querySelector('b')?.textContent?.trim()||'';return t.replace(/^[^\p{L}\p{N}]+/u,'').trim()}
function memberText(x){return `${x.code} ${x.name}${n(x.price)!=null?` · ${fmt(x.price,2)}`:''}${n(x.change)!=null?` ${pct(x.change)}`:''}`}
async function patchSectors(){try{const gm=await groups(),chips=document.querySelectorAll('#sectorList .capital-chip');for(const chip of chips){const g=chipGroup(chip),xs=gm[g]||[];chip.querySelectorAll('.live-sector-preview,.live-sector-members').forEach(x=>x.remove());if(!xs.length)continue;const preview=document.createElement('div');preview.className='live-sector-preview';preview.textContent=`族群股：${xs.slice(0,4).map(x=>`${x.code} ${x.name}`).join('・')}`;const hint=chip.querySelector('.capital-hint');if(hint)hint.before(preview);else chip.appendChild(preview);const more=chip.querySelector('.capital-more');if(more){[...more.querySelectorAll('.capital-hint')].filter(x=>/沒有可對應的成分股|成分股清單/.test(x.textContent||'')).forEach(x=>x.remove());const wrap=document.createElement('div');wrap.className='live-sector-members';wrap.innerHTML=`<div class="live-sector-title">同族群股票（${xs.length}檔）</div><div class="live-sector-list">${xs.slice(0,36).map(x=>`<button type="button" class="live-member-btn" data-live-stock="${esc(x.code)}">${esc(memberText(x))}</button>`).join('')}</div>${xs.length>36?`<div class="capital-hint">先顯示前 36 檔，其餘可用股票搜尋。</div>`:''}`;more.appendChild(wrap)}}}catch(e){console.warn('live sector members patch',e)}}
async function renderSectorRank(group){if(!group)return;try{const gm=await groups(),xs=(gm[group]||[]).slice(0,5),box=$('#sectorRankExplain');if(!box||L.activeGroup!==group)return;box.hidden=false;box.innerHTML=`<div class="live-sector-rank"><div class="live-sector-rank-head"><b>${esc(group)}｜同族群股票</b><span>前 ${xs.length}/${(gm[group]||[]).length} 檔</span></div><div class="live-sector-rank-list">${xs.length?xs.map((x,i)=>`<button type="button" class="live-sector-rank-row" data-live-stock="${esc(x.code)}"><b>${i+1}</b><span><strong>${esc(x.code)} ${esc(x.name)}</strong><small>股價 ${fmt(x.price,2)} · ${pct(x.change)}</small></span><span class="live-sector-rank-score">${esc(cfg(view()).scoreLabel)}<br><b>${fmt(x.score,1)}</b></span></button>`).join(''):'<div class="muted">目前沒有可對應個股。</div>'}</div></div>`}catch(e){console.warn('live sector rank patch',e)}}
async function patchAll(){clearTimeout(L.patchTimer);L.patchTimer=setTimeout(async()=>{await Promise.allSettled([renderBar(),patchPrices(),patchSectors()]);const rb=$('#refreshBtn');if(rb&&!/更新中/.test(rb.textContent||''))rb.textContent='重新整理';if(L.activeGroup)renderSectorRank(L.activeGroup)},80)}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function restoreVisible(target){if(target<=15)return;for(let i=0;i<50;i++){const now=document.querySelectorAll('#cards .card[data-code]').length,btn=$('#loadMore');if(now>=target||!btn||btn.classList.contains('hidden'))break;btn.click();await wait(280)}}
async function softRefresh(){if(L.refreshing)return;L.refreshing=true;const top=$('#livePulseRefresh'),target=document.querySelectorAll('#cards .card[data-code]').length;if(top){top.disabled=true;top.textContent='更新中…'}try{const done=new Promise(resolve=>{let t=setTimeout(resolve,9000);document.addEventListener('radar:data-reloaded',()=>{clearTimeout(t);resolve()},{once:true})}),btn=$('#refreshBtn');if(btn)btn.click();else location.reload();await done;L.manifest=null;await manifest(true);await wait(250);await restoreVisible(target);await patchAll()}finally{L.refreshing=false;if(top){top.disabled=false;top.textContent='重新整理'}}}
async function check(){if(document.hidden||L.refreshing)return;try{const m=await json(`./data/current_manifest.json?autocheck=${Date.now()}`);if(L.build&&m.active_build_id&&m.active_build_id!==L.build)await softRefresh();else{L.manifest=m;L.build=m.active_build_id||L.build;renderBar()}}catch(e){console.warn('live auto refresh',e)}}
function boot(){ensureBar();patchAll();L.timer=setInterval(check,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});document.addEventListener('radar:view-rendered',()=>{L.activeGroup='';patchAll()});document.addEventListener('radar:data-reloaded',()=>{L.manifest=null;L.cache.clear();patchAll()});document.addEventListener('click',e=>{if(e.target.closest?.('#livePulseRefresh')){softRefresh();return}const member=e.target.closest?.('[data-live-stock]');if(member){e.stopPropagation();document.dispatchEvent(new CustomEvent('radar:open-stock',{detail:{code:member.dataset.liveStock}}));return}const chip=e.target.closest?.('#sectorList [data-capital-expand]');if(chip){L.activeGroup=chipGroup(chip);setTimeout(()=>renderSectorRank(L.activeGroup),450);setTimeout(()=>renderSectorRank(L.activeGroup),1200)}},true);const mo=new MutationObserver(()=>patchAll());const cards=$('#cards'),sectors=$('#sectorList');if(cards)mo.observe(cards,{childList:true});if(sectors)mo.observe(sectors,{childList:true,subtree:true})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
